from lib import *
S = SS('p4')
steps = [
    step("连接超时:连一个没人回应的地址(192.0.2.1,RFC 5737 保留给文档的 TEST-NET-1)。timeout=(0.5, 5) 耗时 503 ms 抛 ConnectTimeout,(1.5, 5) 是 1502 ms,单个数 1.0 同时用作连接和读取的超时,1002 ms——耗时就等于设定值。继承关系:ConnectTimeout → ConnectionError → Timeout;ReadTimeout → Timeout,不是 ConnectionError 的子类。本机回环做不出连接超时:macOS 上监听队列满了新连接会被立刻重置,不会卡住。", t=tl(S(1)), done=lidx(S(1), 'timeout=(0.5, 5)', 'timeout=(1.5, 5)', 'timeout=1.0'), mark=lidx(S(1), '异常类的继承关系', 'ReadTimeout 的继承关系'), b=bars([['timeout=(0.5,5) 实际耗时 ms', 503, '503'], ['timeout=1.0 实际耗时 ms', 1002, '1002'], ['timeout=(1.5,5) 实际耗时 ms', 1502, '1502']], 1600, done=[0, 1, 2]), kv=KV([['连接超时', '耗时 ≈ 设定值'], ['ConnectTimeout', '是 ConnectionError 的子类'], ['ReadTimeout', '不是 ConnectionError 的子类']], ['ConnectTimeout'])),
    step("读超时:连上了,服务器过 2 秒才开始回应。timeout=(5, 1.0) 在 1002 ms 抛 ReadTimeout;单个数 1.0 也一样;timeout=(0.2, 3.0) 连接超时设得很短,但连接本机一下就成功了,之后等了 2003 ms 回应到达,成功 200。连接超时只管建立连接,读超时只管“发出请求后等对方数据”,互不影响。", t=tl(S(2)), done=lidx(S(2), 'timeout=(0.2, 3.0)'), mark=lidx(S(2), 'timeout=(5, 1.0)', 'timeout=1.0'), kv=KV([['(5, 1.0)', '1002 ms 后 ReadTimeout'], ['(0.2, 3.0)', '等了 2003 ms,成功 200'], ['连接超时', '连上之后就不再起作用']], ['(0.2, 3.0)'])),
    step("读超时不是总时长,而是“两次数据到达之间最长等多久”。服务器每 0.5 秒发 1 个字节,6 个字节整个响应要 3 秒:timeout=1.0 成功,收到 6 个字节,总耗时 3023 ms,远超 1.0;timeout=0.3 小于 0.5 秒的间隔,在 302 ms 失败。注意异常类:读响应体阶段超时,抛出的是 ConnectionError(消息 Read timed out.),不是 ReadTimeout——requests/models.py 第 942-943 行把 ReadTimeoutError 转成了 ConnectionError。", t=tl(S(3)), done=lidx(S(3), 'timeout=1.0(每个间隔'), mark=lidx(S(3), 'timeout=0.3(每个间隔', 'requests/models.py'), b=bars([['timeout=1.0 总耗时 ms', 3023, '3023'], ['timeout=0.3 失败时 ms', 302, '302']], 3100, done=[0], mark=[1]), kv=KV([['timeout=1.0', '总共 3023 ms 仍成功'], ['timeout=0.3', '读体阶段 ConnectionError'], ['含义', '限制的是每次 recv 的等待']], ['含义'])),
    step("要“总时长上限”requests 没有现成参数。服务器每 0.2 秒发 1 个字节、永远不结束,单独靠 timeout=1.0 永远不会触发(每个间隔才 0.2 秒);我用 stream=True 加自己的循环检查截止时间,2 秒到了主动停止:耗时 2044 ms,收到 10 个字节。慢速“滴灌”的响应能把只设 timeout 的爬虫线程一直占着。", t=tl(S(4)), done=lidx(S(4), '超过自己设的 2 秒截止时间'), b=bars([['自己的截止时间 ms', 2000, '2000'], ['实际耗时 ms', 2044, '2044']], 2100, done=[1], mark=[0]), kv=KV([['只有 timeout=1.0', '永远不会触发'], ['自己检查截止时间', '2044 ms 后停止,收到 10 个字节'], ['做法', 'stream=True + iter_content']], ['做法'])),
    step("不传 timeout 就是 None:requests 文档说 timeout 是“等服务器发送数据多久后放弃”。服务器收到请求后一直不回应,3.0 秒后这个没带 timeout 的请求仍在阻塞(线程还活着,服务器已收到 1 个请求);放行后拿到 200,总耗时 3003 ms。没有 timeout,一个不回应的服务器就能无限期占住一个爬虫线程。", t=tl(S(5)), done=lidx(S(5), '放行之后'), mark=lidx(S(5), '3.0 秒后这个没有 timeout 的请求还在阻塞吗?True'), kv=KV([['默认 timeout', 'None(一直等)'], ['3.0 秒后', '请求仍然阻塞'], ['建议', '每个请求都显式传 timeout']], ['建议'])),
]
A = mkartp('p4', 4, '爬虫,requests,超时,timeout,ConnectTimeout,ReadTimeout,Python,真实验证,动画演示',
    '实测 requests 的 timeout:连接超时耗时恰好等于设定值;读超时限制的是两次数据到达之间的间隔,每 0.5 秒滴灌 1 个字节的 3 秒响应用 timeout=1.0 照样成功;读响应体阶段超时抛的是 ConnectionError 而不是 ReadTimeout;总时长要自己用 stream=True 加截止时间;不传 timeout 就一直阻塞。',
    '“我给 requests 设了 timeout=5,为什么还是卡了一分钟?”因为 timeout 不是总时长。这篇用本机服务器把连接超时、读超时、慢速滴灌的响应、以及不设 timeout 会怎样都复现一遍。',
    [('3023 ms', 'timeout=1.0 却成功:服务器每 0.5 秒发 1 个字节,整个响应用了 3 秒'), ('ConnectionError', '读响应体阶段超时抛的异常,不是 ReadTimeout'), ('True', '不传 timeout,3.0 秒后请求仍在阻塞')],
    [('连接超时', '<p>连一个没人回应的地址,<code>timeout=(0.5, 5)</code> 在 503 ms 抛 <code>ConnectTimeout</code>,耗时就是设定值。<code>ConnectTimeout</code> 继承自 <code>ConnectionError</code>,所以 <code>except ConnectionError</code> 能抓到它;<code>ReadTimeout</code> 不在这条继承链上。</p><p>这里用了 <code>192.0.2.1</code>(RFC 5737 保留给文档的地址,不属于任何真实站点)。本机回环做不出连接超时——macOS 上监听队列满了,新连接会被立刻重置而不是卡住。</p>'),
     ('读超时', '<p>建立连接之后,<code>timeout</code> 的第二个数管“发出请求后等对方数据”。服务器 2 秒后才回应,<code>(5, 1.0)</code> 在约 1 秒时抛 <code>ReadTimeout</code>;<code>(0.2, 3.0)</code> 的连接超时虽然很短,但本机连接瞬间成功,不受影响。</p>'),
     ('不是总时长', '<p>读超时限制的是每次等待数据的时间。服务器每 0.5 秒发一个字节,<code>timeout=1.0</code> 下整个 3 秒的响应照样成功。读响应体阶段超时的异常也不同:requests 在 <code>models.py</code> 里把 <code>ReadTimeoutError</code> 转成了 <code>ConnectionError</code>,所以只捕获 <code>ReadTimeout</code> 会漏掉这种情况。</p>'),
     ('自己做总时长上限', '<p>用 <code>stream=True</code> 配合 <code>iter_content</code>,在循环里检查截止时间,到点主动停止并关闭响应。实测滴灌的响应 2.044 秒后被截断,收到 10 个字节。这只是最简单的做法;我没有测同时限制连接阶段和响应头阶段的总时长。</p>'),
     ('不传 timeout', '<p>默认是 <code>None</code>,也就是一直等。一个收到请求却不回应的服务器,可以让没有 <code>timeout</code> 的请求无限期阻塞。爬虫里每个请求都应显式传 <code>timeout</code>(连接和读取分开传)。</p>')],
    steps,
    [ENV_P + '。连接超时用 RFC 5737 的 TEST-NET-1 地址 192.0.2.1(只发出 SYN,没有回应);其余用本机服务器,分别延迟回应、每 0.5 秒滴灌 1 个字节、每 0.2 秒滴灌且永不结束、收到请求后一直不回应;源码位置取自 requests 的 models.py 与 api.py',
     '没有验证:DNS 解析阶段的耗时是否计入连接超时;TLS 握手阶段的超时归属;代理下的超时语义;aiohttp 的 ClientTimeout(total、connect、sock_read)(后面的文章会单独看);Windows 或 Linux 上监听队列满时的连接表现(只在 macOS 上看到立刻被重置)'],
    'requests 的 timeout')
